using NuclearOptionObserver;
static class HoldControlTests
{
 internal static FlightTelemetry Good()=>new(){Altitude=1000,Speed=150,GroundSpeed=150,AirSpeed=150,VerticalSpeed=0,Pitch=3,Bank=0,Alpha=3,OmegaX=0,OmegaY=0,OmegaZ=0,Slip=0,CourseX=0,CourseZ=1,Throttle=.6f,RadarAltitude=900,MinAirspeed=70,MaxSpeed=400,NozzleAngle=0,CustomAxis=1,Ready=true,GearRetracted=true,AutoHover=false,Damaged=false,EnginesRunning=true,HasSwivel=false,Kind=AirframeKind.FixedWing};
 static void Check(bool v){if(!v)throw new Exception("hold controller assertion failed");}
 public static (string Name,Action Body)[] Cases=>new (string,Action)[]{
  ("controller captures current targets once and zero errors preserve trim throttle",()=>{var f=Good();var c=new FlightHoldCore();Check(c.Capture(f,out _));Check(c.Targets.Altitude==1000&&c.Targets.Speed==150&&c.Targets.CourseZ==1);Check(c.Step(f,.02f,TerrainDemand.Clear,out var cmd,out _)&&cmd.Pitch==0&&cmd.Roll==0&&cmd.Throttle==.6f);f.Altitude=1200;c.Step(f,.02f,TerrainDemand.Clear,out _,out _);Check(c.Targets.Altitude==1000);}),
  ("altitude and bank corrections use actual game pitch and roll signs",()=>{var f=Good();var c=new FlightHoldCore();c.Capture(f,out _);f.Altitude=800;f.Bank=20;Check(c.Step(f,.02f,TerrainDemand.Clear,out var cmd,out _)&&cmd.Pitch<0&&cmd.Roll<0);f=Good();f.CourseX=1;f.CourseZ=0;Check(c.Step(f,.02f,TerrainDemand.Clear,out cmd,out _)&&cmd.Roll<0);}),
  ("angular damping signs oppose native pitch yaw and roll rates",()=>{var f=Good();var c=new FlightHoldCore();c.Capture(f,out _);f.OmegaX=.3f;f.OmegaY=.3f;f.OmegaZ=.3f;Check(c.Step(f,.02f,TerrainDemand.Clear,out var cmd,out _)&&cmd.Pitch<0&&cmd.Yaw<0&&cmd.Roll>0);}),
  ("controller saturation slew and antiwindup recover after opposite speed error",()=>{var c=new FlightHoldCore();var f=Good();c.Capture(f,out _);f.Speed=75;FlightCommand last=default;for(int i=0;i<1000;i++){Check(c.Step(f,.02f,TerrainDemand.Clear,out var cmd,out _));Check(Math.Abs(cmd.Pitch)<=.6f&&Math.Abs(cmd.Roll)<=.75f&&cmd.Throttle<=1&&cmd.Throttle>=0);if(i>0)Check(Math.Abs(cmd.Throttle-last.Throttle)<=.00401f);last=cmd;}Check(last.Throttle>.95f);f.Speed=250;for(int i=0;i<100;i++)Check(c.Step(f,.02f,TerrainDemand.Clear,out last,out _));Check(last.Throttle<.8f);}),
  ("invalid dt or nonfinite telemetry fails without a command",()=>{var c=new FlightHoldCore();var f=Good();c.Capture(f,out _);foreach(float dt in new[]{0f,-1,float.NaN,1})Check(!c.Step(f,dt,TerrainDemand.Clear,out _,out var reason)&&reason.Length>0);f.Speed=float.NaN;Check(!c.Step(f,.02f,TerrainDemand.Clear,out _,out _));}),
  ("global altitude reference is independent of floating origin local offset",()=>{var a=Good();var b=Good();float global=1000,origin=-6000; b.Altitude=(global+origin)-origin;var x=new FlightHoldCore();var y=new FlightHoldCore();Check(x.Capture(a,out _)&&y.Capture(b,out _));a.Altitude=b.Altitude=950;Check(x.Step(a,.02f,TerrainDemand.Clear,out var ca,out _)&&y.Step(b,.02f,TerrainDemand.Clear,out var cb,out _)&&ca.Pitch==cb.Pitch&&x.Targets.Altitude==y.Targets.Altitude);}),
  ("terrain climb prioritizes level bank but never retargets captured altitude",()=>{var f=Good();var c=new FlightHoldCore();c.Capture(f,out _);f.Altitude=1100;f.CourseX=1;f.CourseZ=0;Check(c.Step(f,.02f,new(true,true,12),out var cmd,out _)&&cmd.Pitch<0&&cmd.Roll==0&&c.Targets.Altitude==1000);}),
  ("terrain OFF command does not reset targets or speed integral",()=>{var f=Good();var c=new FlightHoldCore();c.Capture(f,out _);f.Speed=140;for(int i=0;i<50;i++)c.Step(f,.02f,new(true,true,5),out _,out _);Check(c.Step(f,.02f,TerrainDemand.Clear,out var cmd,out _)&&cmd.Throttle>.6f&&c.Targets.Speed==150&&c.Targets.Altitude==1000);}),
  ("terrain throttle floor prevents hidden negative speed integral bias after clear",()=>{var f=Good();var c=new FlightHoldCore();c.Capture(f,out _);f.Speed=160;for(int i=0;i<1000;i++)Check(c.Step(f,.02f,new(true,true,3),out _,out _));f.Speed=150;FlightCommand cmd=default;for(int i=0;i<200;i++)Check(c.Step(f,.02f,TerrainDemand.Clear,out cmd,out _));Check(Math.Abs(cmd.Throttle-.6f)<.001f);}),
  ("eligible forward VTOL requires actual swivel nozzle and forward demand",()=>{var f=Good();f.Kind=AirframeKind.SwivelVtol;f.HasSwivel=true;Check(FlightEnvelope.Check(f,true,out _));f.NozzleAngle=50;Check(!FlightEnvelope.Check(f,true,out _));f.NozzleAngle=0;f.CustomAxis=.3f;Check(!FlightEnvelope.Check(f,true,out _));f.CustomAxis=1;f.HasSwivel=false;Check(!FlightEnvelope.Check(f,true,out _));}),
  ("invalid huge course and nonfinite horizontal ground speed fail closed",()=>{var f=Good();f.CourseX=float.MaxValue;Check(!FlightEnvelope.Check(f,true,out _));f=Good();f.GroundSpeed=float.NaN;Check(!FlightEnvelope.Check(f,true,out _));}),
  ("unknown helicopter tiltwing ground stall damage and engine out are rejected",()=>{foreach(int i in new[]{0,1,2,3,4,5,6}){var f=Good();if(i==0)f.Kind=AirframeKind.Unsupported;if(i==1)f.RadarAltitude=5;if(i==2)f.AirSpeed=30;if(i==3)f.Damaged=true;if(i==4)f.EnginesRunning=false;if(i==5)f.AutoHover=true;if(i==6)f.Bank=90;Check(!FlightEnvelope.Check(f,true,out var reason)&&reason.Length>0);}}),
 };
}
